/**
 * Bilinear-style sample of the heightmap at the chunk-local `(x, z)`
 * point. The heightmap is integer-valued (`number[]`); the pad
 * centre sits inside a `PAD_BLOCK_SIZE_CELLS × PAD_BLOCK_SIZE_CELLS`
 * block that is locally flat, so the bilinear interpolation reduces
 * to the closest cell's height (rounded to the nearest integer).
 */
function sampleHeightAtLocal(
  heightmap: readonly number[],
  x: number,
  z: number,
): number {
  const ix = Math.max(0, Math.min(63, Math.round(x)));
  const iz = Math.max(0, Math.min(63, Math.round(z)));
  return heightmap[iz * 64 + ix] ?? 0;
}

